target.css:
:root {
  --navy: #18344a;
  --navy-deep: #10283b;
  --paper: #fffdf7;
  --mist: #e8f0ee;
  --amber: #e8a52b;
  --amber-pale: #fff0bf;
  --line: #c6d4d4;
  --muted: #607585;
}

* {
  box-sizing: border-box;
}

.shift-card {
  width: 486px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--paper);
  color: var(--navy);
}

.shift-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px;
  border-bottom: 1px solid var(--line);
  background: var(--mist);
}

.station {
  display: flex;
  align-items: center;
  gap: 10px;
}

.beacon {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border-radius: 50%;
  background: var(--navy);
  color: var(--amber);
  font-size: 20px;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
}

.station h1 {
  margin: 0;
  font-size: 18px;
  line-height: 1.1;
}

.ready {
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--amber-pale);
  color: var(--navy-deep);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .6px;
}

.shift-body {
  display: grid;
  grid-template-columns: 1.25fr .85fr;
  gap: 18px;
  padding: 14px 16px;
}

.watch h2 {
  margin: 0 0 3px;
  font-size: 20px;
  line-height: 1.15;
}

.watch > p:not(.eyebrow) {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
}

.tasks {
  display: grid;
  gap: 4px;
  margin: 12px 0 0;
  padding: 0;
  list-style: none;
  font-size: 13px;
}

.tasks li::before {
  margin-right: 7px;
  color: var(--amber);
  content: "●";
}

.timeline {
  display: grid;
  gap: 2px;
  padding-left: 14px;
  border-left: 2px solid var(--amber);
  align-content: center;
}

.timeline span {
  margin-top: 3px;
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .8px;
}

.timeline strong {
  font-size: 13px;
  line-height: 1.2;
}

.shift-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  background: var(--navy-deep);
}

.seal {
  color: var(--mist);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
}

.acknowledge {
  border: 0;
  border-radius: 7px;
  padding: 8px 11px;
  background: var(--amber);
  color: var(--navy-deep);
  font-size: 12px;
  font-weight: 800;
}

